<original_code>
#include <bits/stdc++.h>
#define err(...) {}
#ifdef DEBUG
#include "_debug.cpp"
#include "callable.hpp/callable.hpp"
#endif
#define endl '\n'
using namespace std;
using llong = long long;
const int LIMIT = 10;
char world[LIMIT][LIMIT];
int pop[LIMIT][LIMIT];
int help[LIMIT][LIMIT];
int fire[LIMIT][LIMIT];
const int dx[4] = {-1, 1, 0, 0};
const int dy[4] = {0, 0, -1, 1};
int time_to_reach[LIMIT][LIMIT][LIMIT][LIMIT];
const int TOTAL_NODES = 2 * LIMIT * LIMIT + 2;
const int MAX_VAL = 1000000000;
vector<int> g[TOTAL_NODES + 1];
int cap[TOTAL_NODES + 1][TOTAL_NODES + 1], flow[TOTAL_NODES + 1][TOTAL_NODES + 1];
int depth[TOTAL_NODES + 1], prev_node[TOTAL_NODES + 1], cursor[TOTAL_NODES + 1];

bool level_bfs(int s, int t) {
    fill(depth, depth + TOTAL_NODES + 1, -1);
    depth[s] = 0;
    queue<int> q;
    q.push(s);
    while (!q.empty()) {
        int u = q.front(); q.pop();
        for (int v : g[u]) {
            if (cap[u][v] - flow[u][v] > 0 && depth[v] == -1) {
                depth[v] = depth[u] + 1;
                q.push(v);
            }
        }
    }
    return depth[t] != -1;
}

bool dfs_flow(int u, int t) {
    if (u == t) return true;
    for (int& i = cursor[u]; i < (int)g[u].size(); ++i) {
        int v = g[u][i];
        if (depth[v] == depth[u] + 1 && cap[u][v] - flow[u][v] > 0 && dfs_flow(v, t)) {
            prev_node[v] = u;
            return true;
        }
    }
    return false;
}

bool find_path(int s, int t) {
    fill(prev_node, prev_node + TOTAL_NODES + 1, -1);
    prev_node[s] = 0;
    return dfs_flow(s, t);
}

void clear_flow_data() {
    memset(cap, 0, sizeof cap);
    memset(flow, 0, sizeof flow);
}

void add_connection(int u, int v, int capacity) {
    g[u].push_back(v);
    g[v].push_back(u);
    cap[u][v] += capacity;
}

int dinic_algorithm(int s, int t) {
    int flow_value = 0;
    while (level_bfs(s, t)) {
        fill(cursor, cursor + TOTAL_NODES + 1, 0);
        while (find_path(s, t)) {
            int bottleneck = MAX_VAL;
            for (int v = t, u = prev_node[v]; v != s; v = u, u = prev_node[v]) {
                bottleneck = min(bottleneck, cap[u][v] - flow[u][v]);
            }
            for (int v = t, u = prev_node[v]; v != s; v = u, u = prev_node[v]) {
                flow[u][v] += bottleneck;
                flow[v][u] -= bottleneck;
            }
            flow_value += bottleneck;
        }
    }
    return flow_value;
}

int vertex(int size, int r, int c, bool is_right) {
    return r * size + c + (is_right ? size * size : 0);
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, time_limit;
    cin >> n >> time_limit;
    string line;
    pair<int, int> origin;
    for (int i = 0; i < n; ++i) {
        cin >> line;
        for (int j = 0; j < n; ++j) {
            if (line[j] == 'Y') {
                world[i][j] = 'Y';
            } else if (line[j] == 'Z') {
                world[i][j] = 'Z';
                origin = {i, j};
            } else {
                world[i][j] = '.';
                pop[i][j] += line[j] - '0';
            }
        }
    }
    for (int i = 0; i < n; ++i) {
        cin >> line;
        for (int j = 0; j < n; ++j) {
            if (line[j] != 'Y' && line[j] != 'Z') {
                help[i][j] += line[j] - '0';
            }
        }
    }
    memset(fire, -1, sizeof fire);
    fire[origin.first][origin.second] = 0;
    queue<pair<int, int>> q;
    q.push(origin);
    while (!q.empty()) {
        int x = q.front().first, y = q.front().second;
        q.pop();
        for (int k = 0; k < 4; ++k) {
            int nx = x + dx[k], ny = y + dy[k];
            if (0 <= nx && nx < n && 0 <= ny && ny < n && world[nx][ny] == '.' && fire[nx][ny] == -1) {
                fire[nx][ny] = fire[x][y] + 1;
                q.push({nx, ny});
            }
        }
    }
    memset(time_to_reach, -1, sizeof time_to_reach);
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            if (world[i][j] == '.') {
                time_to_reach[i][j][i][j] = 0;
                queue<pair<int, int>> bfs;
                bfs.push({i, j});
                while (!bfs.empty()) {
                    int r = bfs.front().first, c = bfs.front().second;
                    bfs.pop();
                    if (fire[r][c] == -1 || time_to_reach[i][j][r][c] < fire[r][c]) {
                        for (int k = 0; k < 4; ++k) {
                            int nr = r + dx[k], nc = c + dy[k];
                            if (0 <= nr && nr < n && 0 <= nc && nc < n && world[nr][nc] == '.' &&
                                (fire[nr][nc] == -1 || time_to_reach[i][j][r][c] + 1 <= fire[nr][nc]) &&
                                time_to_reach[i][j][nr][nc] == -1) {
                                time_to_reach[i][j][nr][nc] = time_to_reach[i][j][r][c] + 1;
                                bfs.push({nr, nc});
                            }
                        }
                    }
                }
            }
        }
    }
    int source = 2 * n * n, sink = 2 * n * n + 1;
    clear_flow_data();
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            if (pop[i][j]) {
                add_connection(source, vertex(n, i, j, false), pop[i][j]);
            }
            if (help[i][j]) {
                add_connection(vertex(n, i, j, true), sink, help[i][j]);
            }
            for (int ri = 0; ri < n; ++ri) {
                for (int rj = 0; rj < n; ++rj) {
                    if (time_to_reach[i][j][ri][rj] != -1 && time_to_reach[i][j][ri][rj] <= time_limit) {
                        add_connection(vertex(n, i, j, false), vertex(n, ri, rj, true), MAX_VAL);
                    }
                }
            }
        }
    }
    cout << dinic_algorithm(source, sink) << endl;
    return 0;
}
